import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        new EHeightAllTheSame().solve(br, out);
        out.close();
    }

    static class EHeightAllTheSame {
        void solve(BufferedReader br, PrintWriter out) throws IOException {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long n = Long.parseLong(st.nextToken());
            long m = Long.parseLong(st.nextToken());
            long k = n * m;
            long l = Long.parseLong(st.nextToken());
            long r = Long.parseLong(st.nextToken());
            long len = r - l + 1;
            long mod = 998244353L;

            if (k % 2 == 1) {
                out.println(powMod(len, k, mod));
                return;
            }

            long ans = (powMod(len, k, mod) + powMod(len % 2, k, mod)) * powMod(2, mod - 2, mod) % mod;
            out.println(ans);
        }

        private static long powMod(long base, long exp, long mod) {
            long result = 1;
            base %= mod;
            while (exp > 0) {
                if ((exp & 1) == 1) result = (result * base) % mod;
                exp >>= 1;
                base = (base * base) % mod;
            }
            return result;
        }
    }
}
